using ManufacturerERP.Data; using ManufacturerERP.Models; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace ManufacturerERP.Services;
public interface IProcurementService { Task ApproveOrderAsync(int id, ClaimsPrincipal user); Task ConfirmReceiptAsync(int id, ClaimsPrincipal user); Task ConfirmInvoiceAsync(int id, ClaimsPrincipal user); Task RecordPaymentAsync(SupplierPayment payment, ClaimsPrincipal user); Task<string> NextNumberAsync(string prefix); }
public class ProcurementService(ApplicationDbContext db, IAuditService audit) : IProcurementService
{
    public async Task<string> NextNumberAsync(string prefix) { var count=prefix switch {"PO"=>await db.PurchaseOrders.CountAsync(),"GR"=>await db.GoodsReceipts.CountAsync(),"PI"=>await db.PurchaseInvoices.CountAsync(),_=>await db.SupplierPayments.CountAsync()}; return $"{prefix}-{count+1:000000}"; }
    public async Task ApproveOrderAsync(int id, ClaimsPrincipal user) { var po=await db.PurchaseOrders.FindAsync(id)??throw new InvalidOperationException("Purchase order not found."); if(po.Status!=PurchaseOrderStatus.Draft)throw new InvalidOperationException("Only draft orders can be approved."); po.Status=PurchaseOrderStatus.Approved;po.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(user,"Approve","PurchaseOrder",id,$"Approved {po.Number}"); }
    public async Task ConfirmReceiptAsync(int id, ClaimsPrincipal user) { await using var tx=await db.Database.BeginTransactionAsync(); var gr=await db.GoodsReceipts.Include(x=>x.Items).ThenInclude(x=>x.PurchaseOrderItem).FirstOrDefaultAsync(x=>x.Id==id)??throw new InvalidOperationException("Receipt not found."); if(gr.Status!=GoodsReceiptStatus.Draft)throw new InvalidOperationException("Only draft receipts can be confirmed."); var po=await db.PurchaseOrders.Include(x=>x.Items).FirstAsync(x=>x.Id==gr.PurchaseOrderId); if(po.Status is not (PurchaseOrderStatus.Approved or PurchaseOrderStatus.PartiallyReceived))throw new InvalidOperationException("The order is not available for receiving."); foreach(var item in gr.Items){if(item.ReceivingQuantity<=0||item.PurchaseOrderItem is null||item.ReceivingQuantity>item.PurchaseOrderItem.Quantity-item.PurchaseOrderItem.ReceivedQuantity)throw new InvalidOperationException("Receiving quantity exceeds the open purchase-order quantity."); item.PurchaseOrderItem.ReceivedQuantity+=item.ReceivingQuantity;db.InventoryTransactions.Add(new InventoryTransaction {ProductId=item.ProductId,WarehouseId=gr.WarehouseId,TransactionType=InventoryTransactionType.PurchaseReceipt,Quantity=item.ReceivingQuantity,UnitCost=item.UnitPrice,ReferenceType="GoodsReceipt",ReferenceId=gr.Id,TransactionDate=gr.ReceiptDate,Notes=gr.Notes,CreatedById=user.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value});} gr.Status=GoodsReceiptStatus.Confirmed;po.Status=po.Items.All(x=>x.ReceivedQuantity>=x.Quantity)?PurchaseOrderStatus.Received:PurchaseOrderStatus.PartiallyReceived;await db.SaveChangesAsync();await audit.LogAsync(user,"Confirm","GoodsReceipt",id,$"Confirmed {gr.Number}; inventory posted");await tx.CommitAsync(); }
    public async Task ConfirmInvoiceAsync(int id, ClaimsPrincipal user) { var invoice=await db.PurchaseInvoices.FindAsync(id)??throw new InvalidOperationException("Invoice not found.");if(invoice.Status!=PurchaseInvoiceStatus.Draft)throw new InvalidOperationException("Only draft invoices can be confirmed.");invoice.Status=PurchaseInvoiceStatus.Confirmed;await db.SaveChangesAsync();await audit.LogAsync(user,"Confirm","PurchaseInvoice",id,$"Confirmed {invoice.Number}; payable created"); }
    public async Task RecordPaymentAsync(SupplierPayment payment, ClaimsPrincipal user) { await using var tx=await db.Database.BeginTransactionAsync();var invoice=await db.PurchaseInvoices.Include(x=>x.Payments).FirstOrDefaultAsync(x=>x.Id==payment.PurchaseInvoiceId)??throw new InvalidOperationException("Invoice not found.");if(invoice.Status is not (PurchaseInvoiceStatus.Confirmed or PurchaseInvoiceStatus.PartiallyPaid))throw new InvalidOperationException("Invoice is not payable.");var outstanding=invoice.GrandTotal-invoice.Payments.Sum(x=>x.Amount);if(payment.Amount<=0||payment.Amount>outstanding)throw new InvalidOperationException("Payment must not exceed invoice outstanding amount.");payment.SupplierId=invoice.SupplierId;payment.Number=await NextNumberAsync("PAY");payment.CreatedById=user.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;db.SupplierPayments.Add(payment);await db.SaveChangesAsync();invoice.Status=payment.Amount==outstanding?PurchaseInvoiceStatus.Paid:PurchaseInvoiceStatus.PartiallyPaid;await db.SaveChangesAsync();await audit.LogAsync(user,"Create","SupplierPayment",payment.Id,$"Recorded {payment.Number} against {invoice.Number}");await tx.CommitAsync(); }
}
